        interceptors: self.interceptors?.makePlayInterceptors() ?? [],
        userFunction: self.play(request:context:)
      )

    case "Stop":
      return UnaryServerHandler(
        context: context,
        requestDeserializer: ProtobufDeserializer<Beebium_StopRequest>(),
        responseSerializer: ProtobufSerializer<Beebium_CassetteResponse>(),
