/// The cassette deck behind the Serial ULA's cassette interface.
///
/// One deck, so no drive number anywhere. The deck is the user's transport:
/// inserting leaves it stopped at the start, and play is a separate request. The
/// tape moves only while the deck plays and the machine's motor relay (Serial
/// ULA latch bit 7) is closed. Every unsuccessful response carries a sentence
/// naming the tape by the name the client gave, and a kind.
///
/// To implement a server, implement an object which conforms to this protocol.
@available(macOS 10.15, iOS 13, tvOS 13, watchOS 6, *)
public protocol Beebium_CassetteServiceAsyncProvider: CallHandlerProvider, Sendable {
  static var serviceDescriptor: GRPCServiceDescriptor { get }
  var interceptors: Beebium_CassetteServiceServerInterceptorFactoryProtocol? { get }

  /// Insert a UEF or CSW tape image the server can reach. The format is
  /// judged by content. Fails if a tape is already in.
  func insertTape(
    request: Beebium_InsertTapeRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_InsertTapeResponse

  /// Stop and remove the tape.
  func ejectTape(
    request: Beebium_EjectTapeRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  /// The deck's keys. Play at the end of the tape succeeds and leaves the
  /// deck stopped at the end. Seek beyond the end lands at the end.
  func play(
    request: Beebium_PlayRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  func stop(
    request: Beebium_StopRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  func seek(
    request: Beebium_SeekRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  /// Wind the tape backwards or forwards at 30 times real speed, whether or
  /// not the relay is closed; nothing reaches the Serial ULA while it winds.
  /// The wind ends on Stop, Play, Seek or EjectTape, or at an end of the
  /// tape, where the deck stops. Seek to 0 is the instant return to the start.
  func rewind(
    request: Beebium_RewindRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  func fastForward(
    request: Beebium_FastForwardRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  /// Press record. From here, while the relay is closed, the tape moves and
  /// what passes under the head is replaced by what the Serial ULA sends, an
  /// edge or silence. Stop, Play, Seek, a wind, EjectTape and the end of the
  /// tape end it, and the tape is then written back to its file. Refused with
  /// READ_ONLY for a tape Beebium only reads (a CSW).
  func record(
    request: Beebium_RecordRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CassetteResponse

  /// The blank tape templates the server ships, and a copy of one into place
  /// on the server's host, as DiscService's ListBlankDiscs and CreateDisc.
  func listBlankTapes(
    request: Beebium_ListBlankTapesRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_ListBlankTapesResponse

  func createTape(
    request: Beebium_CreateTapeRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_CreateTapeResponse

  /// A live audio input, streamed by a client from its host: the stream is
  /// the live tape. The first message is the format, once; the rest are
  /// samples. Refused with DECK_OCCUPIED while a tape is in, and with
  /// INVALID_FORMAT if the first message is not a format or a second one
  /// comes. A valid format inserts the live tape, stopped; the client then
  /// calls Play. The relay does not gate it. Closing the stream ejects it,
  /// and EjectTape ends the stream. The ring between the stream and the
  /// emulation absorbs the drift between the host's clock and emulated
  /// time; there is no resampling, so a live load is for real speed.
  func streamAudio(
    requestStream: GRPCAsyncRequestStream<Beebium_AudioInputChunk>,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_StreamAudioSummary

  /// The deck's state, read without stopping the machine.
  func getDeckStatus(
    request: Beebium_GetDeckStatusRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_DeckStatus

  /// The current status at once, then a status on every change of presence,
  /// transport, relay or tape, and while the deck plays the position no more
  /// often than min_interval_ms of emulated time.
  func subscribeDeckStatus(
    request: Beebium_SubscribeDeckStatusRequest,
    responseStream: GRPCAsyncResponseStreamWriter<Beebium_DeckStatus>,
    context: GRPCAsyncServerCallContext
  ) async throws

  /// Where the tape carries signal, a level a second, computed off the
  /// emulation thread when a tape is inserted and again when a recording
  /// ends. Until it is ready, and for a live tape, ready is false;
  /// DeckStatus.signal_map_generation says when to fetch it again.
  func getTapeSignalMap(
    request: Beebium_GetTapeSignalMapRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_TapeSignalMap

  /// Seek to the append point: the end of the last second of the signal map
  /// with any signal, plus two seconds, so a new recording follows the last
  /// one with a short gap; the start for a silent tape. As Seek, it ends a
  /// recording or a wind first, and a playing deck plays on; a point at or
  /// past the end stops the deck at the end, and at_end says so. Refused
  /// with DECK_EMPTY, LIVE_SOURCE, or NOT_READY before the map is computed;
  /// DeckStatus.append_refusal carries the sentence it would refuse with.
  func seekToAppendPoint(
    request: Beebium_SeekToAppendPointRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> Beebium_SeekToAppendPointResponse
}

